import { test, expect } from '@playwright/test';

test.describe('Sauce Demo Login', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should display login form with required fields', async ({ page }) => {
    const usernameField = page.locator('[data-test="username"]');
    const passwordField = page.locator('[data-test="password"]');
    const loginButton = page.locator('[data-test="login-button"]');

    await expect(usernameField).toBeVisible();
    await expect(passwordField).toBeVisible();
    await expect(loginButton).toBeVisible();
  });

  test('should successfully log in with valid credentials and redirect to inventory', async ({ page }) => {
    const usernameField = page.locator('[data-test="username"]');
    const passwordField = page.locator('[data-test="password"]');
    const loginButton = page.locator('[data-test="login-button"]');

    await usernameField.fill('standard_user');
    await passwordField.fill('secret_sauce');
    await loginButton.click();

    await page.waitForURL('**/inventory.html');
    expect(page.url()).toContain('/inventory.html');

    const titleElement = page.locator('.title');
    await expect(titleElement).toHaveText('Products');
  });

  test('should display error message with invalid credentials', async ({ page }) => {
    const usernameField = page.locator('[data-test="username"]');
    const passwordField = page.locator('[data-test="password"]');
    const loginButton = page.locator('[data-test="login-button"]');

    await usernameField.fill('invalid_user');
    await passwordField.fill('wrong_password');
    await loginButton.click();

    const errorMessage = page.locator('[data-test="error"]');
    await expect(errorMessage).toBeVisible();
  });
});
